(255579, 17477, 5212, '<td valign="top">A little more grain than I like., but love this anyway. 9</td>', 'A little more grain than I like., but love this anyway. 9', '2003-04-07 01:15:19.000000', NULL, 1),
(255587, 17311, 5212, '<td valign="top">A little grainy, but definitely an eye catcher.</td>', 'A little grainy, but definitely an eye catcher.', '2003-04-07 01:17:13.000000', NULL, 1),
(255591, 17335, 5212, '<td valign="top">Great shot, only thing I might change is that bright area in the lower left.  Good luck, 8</td>', 'Great shot, only thing I might change is that bright area in the lower left.  Good luck, 8', '2003-04-07 01:18:05.000000', NULL, 1),
