(255635, 17357, 5212, '<td valign="top">The blue contrasting with the yellow works very well here. 8</td>', 'The blue contrasting with the yellow works very well here. 8', '2003-04-07 01:34:00.000000', NULL, 1),
(255637, 17126, 5400, '<td valign="top">I think it looks a little over-sharpened.</td>', 'I think it looks a little over-sharpened.', '2003-04-07 01:34:26.000000', NULL, 1),
