(257314, 17438, 3981, '<td valign="top">Artistry in color!! Great composition coming from the lower left to upper right.  Has to be a winner!  Top 3, I would guess.</td>', 'Artistry in color!! Great composition coming from the lower left to upper right.  Has to be a winner!  Top 3, I would guess.', '2003-04-07 18:08:39.000000', NULL, 1),
(257315, 17300, 4494, '<td valign="top">A little titled to the left.  Nice shot, good colors.  Maybe slightly under-exposed.</td>', 'A little titled to the left.  Nice shot, good colors.  Maybe slightly under-exposed.', '2003-04-07 18:08:52.000000', NULL, 1),
(257318, 17318, 4210, '<td valign="top">Would have cropped this one a little closer...</td>', 'Would have cropped this one a little closer...', '2003-04-07 18:09:51.000000', NULL, 1),
