(261575, 17508, 4049, '<td valign="top">cool building, I love the various shades.</td>', 'cool building, I love the various shades.', '2003-04-10 10:32:32.000000', NULL, 1),
(261577, 17538, 5728, '<td valign="top">Clever! You pulled this one off well, I like it.</td>', 'Clever! You pulled this one off well, I like it.', '2003-04-10 10:36:23.000000', NULL, 1),
(261579, 17215, 5728, '<td valign="top">Choice! Absolutely no reflections and the lighting is optimal, I really like this one.</td>', 'Choice! Absolutely no reflections and the lighting is optimal, I really like this one.', '2003-04-10 10:43:23.000000', NULL, 1),
